import assert from 'node:assert/strict';
import { mergeConfig } from '../src/config.js';

function freeze(value) {
  if (value && typeof value === 'object') {
    for (const child of Object.values(value)) freeze(child);
    Object.freeze(value);
  }
  return value;
}

if (process.argv[2] === 'recursive') {
  const defaults = freeze({ server: { host: 'localhost', port: 8080 }, level: 'info' });
  const overrides = freeze({ server: { port: 9090 } });
  assert.deepEqual(mergeConfig(defaults, overrides), {
    server: { host: 'localhost', port: 9090 }, level: 'info'
  });
  assert.deepEqual(defaults, { server: { host: 'localhost', port: 8080 }, level: 'info' });
  assert.deepEqual(overrides, { server: { port: 9090 } });

  const a = freeze({ service: { tls: { options: { enabled: true, retries: 3, headers: { accept: 'json', agent: 'old' } }, cert: 'default' }, host: 'local' }, untouched: { x: 1 } });
  const b = freeze({ service: { tls: { options: { retries: 7, headers: { agent: 'new', token: 'secret' } } }, extra: 42 } });
  assert.deepEqual(mergeConfig(a, b), {
    service: { tls: { options: { enabled: true, retries: 7, headers: { accept: 'json', agent: 'new', token: 'secret' } }, cert: 'default' }, host: 'local', extra: 42 }, untouched: { x: 1 }
  });
  assert.deepEqual(mergeConfig({ a: { b: { c: 1 } } }, { a: {} }), { a: { b: { c: 1 } } });
  // Depth must not be limited to a fixed number of levels.
  let left = { keep: 'yes', change: 1 };
  let right = { change: 2 };
  let expected = { keep: 'yes', change: 2 };
  for (let i = 0; i < 40; i++) {
    left = { child: left, sibling: i };
    right = { child: right };
    expected = { child: expected, sibling: i };
  }
  freeze(left); freeze(right);
  assert.deepEqual(mergeConfig(left, right), expected);
  // Plain records with null prototypes still have mergeable own keys.
  const nullLeft = Object.assign(Object.create(null), { keep: 1, change: 2 });
  const nullRight = Object.assign(Object.create(null), { change: 3 });
  const record = mergeConfig({ record: nullLeft }, { record: nullRight }).record;
  assert.equal(record.keep, 1);
  assert.equal(record.change, 3);
} else if (process.argv[2] === 'compatibility') {
  assert.deepEqual(mergeConfig({ level: 'info', color: true }, { level: 'debug', file: 'app.log' }), { level: 'debug', color: true, file: 'app.log' });
  assert.deepEqual(mergeConfig({}, {}), {});
  assert.deepEqual(mergeConfig({ a: 1 }, {}), { a: 1 });
  assert.deepEqual(mergeConfig({}, { a: 1 }), { a: 1 });
  class Setting { constructor() { this.value = 9; } }
  const replacements = [['c'], [], null, 'text', '', 0, 12, false, true, undefined, new Date(0), new Setting()];
  for (const replacement of replacements) {
    const defaults = freeze({ value: { keep: 1, child: { a: 2 } }, sibling: 'keep' });
    const overrides = freeze({ value: replacement });
    const result = mergeConfig(defaults, overrides);
    assert.deepEqual(result, { value: replacement, sibling: 'keep' });
    assert.ok(Object.hasOwn(result, 'value'));
    assert.deepEqual(defaults, { value: { keep: 1, child: { a: 2 } }, sibling: 'keep' });
    assert.deepEqual(overrides, { value: replacement });
  }
  assert.deepEqual(mergeConfig({ tags: ['a', 'b'] }, { tags: ['c'] }), { tags: ['c'] });
  for (const old of [null, 1, 'old', ['old']]) {
    assert.deepEqual(mergeConfig({ value: old }, { value: { added: 1 } }), { value: { added: 1 } });
  }
  const defaults = freeze({ a: 1, kept: { x: 2 } });
  const overrides = freeze({ a: 2, added: { y: 3 } });
  const result = mergeConfig(defaults, overrides);
  assert.notStrictEqual(result, defaults);
  assert.notStrictEqual(result, overrides);
  result.a = 10;
  assert.equal(defaults.a, 1);
  assert.equal(overrides.a, 2);
} else {
  throw new Error('Choose recursive or compatibility');
}
